#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/events/input_events/input_events.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// DockNavigator's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/dock_navigator.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The modifier whose release chooses the current row, as releasing Ctrl ends Ctrl+Tab; none (the default) leaves choosing to Enter or a click. Anything but none, control, alt or meta throws std::invalid_argument and changes nothing.
template <typename Declaring>
struct DockNavigatorReleaseModifierCapability {
    PropertyCell<Modifier, DockNavigatorReleaseModifierCapability<Declaring>> release_modifier{Modifier::none};

    static void assign(DockNavigatorReleaseModifierCapability& capability, Modifier incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.release_modifier), incoming);
        if (!capability.release_modifier.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.release_modifier));
    }
};

// Every DockNavigator capability, in the order the declaring class takes them.
template <typename Declaring>
struct DockNavigatorCapabilities : public DockNavigatorReleaseModifierCapability<Declaring> {};

} // namespace gui_forms
